//! Bounded, metadata-only diagnostics. Reading a snapshot never accesses a port.
//! AI-generated by GPT 6.1 Sol (OpenAI) via OpenCode; no independent human review claimed.
use std::collections::VecDeque;
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::{Arc, Mutex};
use std::time::Instant;

const EVENTS: usize = 256;
static SESSION: AtomicU64 = AtomicU64::new(1);

#[derive(Clone, Debug)]
pub struct Event {
    pub elapsed_ms: u64,
    pub name: &'static str,
    pub kind: &'static str,
    pub total: usize,
    pub offset: usize,
    pub duration_ms: u64,
    pub error_kind: Option<String>,
    pub os_error: Option<i32>,
}

#[derive(Clone, Debug, Default)]
pub struct Snapshot {
    pub session: u64,
    pub transport: String,
    pub connected: bool,
    pub elapsed_ms: u64,
    pub updated_ms: u64,
    pub rx_buffer: usize,
    pub read_timeout_ms: Option<u64>,
    pub write_attempt_timeout_ms: Option<u64>,
    pub write_deadline_ms: u64,
    pub sent_lines: usize,
    pub acknowledged_lines: usize,
    pub inflight_lines: usize,
    pub inflight_bytes: usize,
    pub oldest_ack_age_ms: Option<u64>,
    pub job_next: Option<usize>,
    pub job_total: Option<usize>,
    pub job_acked: Option<usize>,
    pub paused: bool,
    pub last_status: Option<String>,
    pub last_rx_ms: Option<u64>,
    pub last_ack_ms: Option<u64>,
    pub last_error: Option<String>,
    pub pending_kind: Option<&'static str>,
    pub pending_total: usize,
    pub pending_offset: usize,
    pub events: VecDeque<Event>,
    pub dropped_updates: u64,
}

#[derive(Clone)]
pub struct Diagnostics {
    inner: Arc<Mutex<Snapshot>>,
    start: Instant,
    dropped: Arc<AtomicU64>,
}

impl Default for Diagnostics {
    fn default() -> Self {
        Self { inner: Arc::new(Mutex::new(Snapshot::default())), start: Instant::now(), dropped: Arc::new(AtomicU64::new(0)) }
    }
}

pub fn millis(time: std::time::Duration) -> u64 {
    time.as_millis().min(u128::from(u64::MAX)) as u64
}

impl Diagnostics {
    pub fn new(transport: &str, rx_buffer: usize, serial: bool) -> Self {
        let result = Self::default();
        result.update(|s| {
            s.session = SESSION.fetch_add(1, Ordering::Relaxed);
            s.transport = match transport {
                "serial" => "serial", "tcp" => "tcp", "ws" => "ws",
                "memory" => "memory", "test-or-unspecified" => "test-or-unspecified",
                _ => "unknown",
            }.to_owned();
            s.connected = false;
            s.rx_buffer = rx_buffer;
            s.read_timeout_ms = Some(10);
            s.write_attempt_timeout_ms = if serial { Some(if cfg!(windows) { 50 } else { 10 }) } else { None };
            s.write_deadline_ms = 2000;
        });
        result
    }

    pub fn elapsed_ms(&self) -> u64 { millis(self.start.elapsed()) }

    /// Contended diagnostics must never stall the machine worker.
    pub fn update(&self, apply: impl FnOnce(&mut Snapshot)) {
        if let Ok(mut state) = self.inner.try_lock() {
            state.updated_ms = self.elapsed_ms();
            apply(&mut state);
        } else {
            self.dropped.fetch_add(1, Ordering::Relaxed);
        }
    }

    pub fn event(&self, name: &'static str, kind: &'static str, total: usize, offset: usize, duration_ms: u64, error: Option<&std::io::Error>) {
        self.update(|s| {
            if s.events.len() == EVENTS { s.events.pop_front(); }
            s.events.push_back(Event {
                elapsed_ms: self.elapsed_ms(), name, kind, total, offset, duration_ms,
                error_kind: error.map(|e| format!("{:?}", e.kind())),
                os_error: error.and_then(std::io::Error::raw_os_error),
            });
        });
    }

    pub fn snapshot(&self) -> Result<Snapshot, String> {
        let mut state = self.inner.lock().map_err(|_| "Diagnostics lock is unavailable".to_owned())?.clone();
        state.elapsed_ms = self.elapsed_ms();
        state.dropped_updates = self.dropped.load(Ordering::Relaxed);
        // These are observation ages, not freshly queried controller evidence.
        if let Some(age) = &mut state.oldest_ack_age_ms {
            *age = age.saturating_add(state.elapsed_ms.saturating_sub(state.updated_ms));
        }
        Ok(state)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn transport_labels_do_not_retain_caller_supplied_text() {
        for label in ["serial", "tcp", "ws", "memory", "test-or-unspecified"] {
            assert_eq!(Diagnostics::new(label, 127, false).snapshot().unwrap().transport, label);
        }
        let d = Diagnostics::new("PRIVATE_TRANSPORT_MARKER", 127, false);
        assert_eq!(d.snapshot().unwrap().transport, "unknown");
        assert!(!format!("{:?}", d.snapshot().unwrap()).contains("PRIVATE_"));
    }
    #[test]
    fn new_session_does_not_claim_a_connection_before_open() {
        let d = Diagnostics::new("serial", 127, true);
        assert!(!d.snapshot().unwrap().connected);
    }
    #[test]
    fn ring_is_bounded_and_contains_only_metadata() {
        let d = Diagnostics::new("serial", 127, true);
        for _ in 0..1000 { d.event("write", "job", 20, 4, 1, None); }
        let s = d.snapshot().unwrap();
        assert_eq!(s.events.len(), EVENTS);
        assert!(s.session > 0);
        assert_eq!(s.events[0].offset, 4);
    }
    #[test]
    fn contention_drops_observations_instead_of_blocking_worker() {
        let d = Diagnostics::default();
        let guard = d.inner.lock().unwrap();
        d.event("write", "status", 1, 0, 0, None);
        drop(guard);
        assert_eq!(d.snapshot().unwrap().dropped_updates, 1);
    }
}
